// st03bs.ecl.txt:972 ANGLE_ACCEL: a=50, r=0.02/0.03 per frame, s=+/-2deg per frame.
// The accel starts after the WAIT 10 at :962; the parent is deleted when SHOOT fires (:991).
xformdef AT_PARENT(accel: fx, spin: angle) {
    @10 add_speed(0fx);
    set_accel(accel);
    set_ang_vel(spin);
    @50 add_speed(0fx);
    stop_fx();
    set_life(1);
}

// st03bs.ecl.txt:1024/:1074 VELTIME: a=60, direction kept, scalar speed ramps 0 -> target.
xformdef RAMP(delta: fx) {
    set_accel(delta);
    @60 add_speed(0fx);
    stop_fx();
}

// st03bs.ecl.txt:767-769: moveLimit(0,128,280,64) then movePosTime(60,4,160,64).
// Limit box is x[-140,140], y[96,160]; :779 moveLimitReset() clears it afterwards,
// so only this intro move is clamped per frame.
sub intro_move(tx: fx, ty: fx, frames: int) {
    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var k: int = 0;
    while k < frames {
        k = k + 1;
        var u: fx = (k as fx) / (frames as fx);
        var e: fx = u * (2fx - u);          // movePosTime mode 4 = quad out
        var nx: fx = x0 + (tx - x0) * e;
        var ny: fx = y0 + (ty - y0) * e;
        if nx > 140fx { nx = 140fx; }
        if nx < -140fx { nx = -140fx; }
        if ny > 160fx { ny = 160fx; }
        if ny < 96fx { ny = 96fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
}

// st03bs.ecl.txt:1084-1103: while $GI0>=0, after 20 frames clear bullets
// within 32px of the boss every frame (etClear runs on the boss itself).
async sub boss_et_break() {
    var a: int = 0;
    loop {
        if self_int(0) >= 0 {
            if a >= 20 { clear_bullets_at($self_x, $self_y, 32fx, 0); }
            a = a + 1;
        } else {
            a = 0;
        }
        wait(1);
    }
}

// st03bs.ecl.txt:951-999 BossCard3_at: 8-way ring at 32px, speed 0,
// ANGLE_ACCEL for 50 frames, then SHOOT splits into random children and deletes parent.
async sub at_ring(spin: angle, accel: fx) {
    var base: angle = rand(65536) as angle;   // :957 %RANDRAD
    sh_reset(0);
    sh_sprite(0, AT_SHAPE, AT_COLOR);
    sh_ring(0, 1);                            // etAim 3: fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, 8, 1);
    sh_angle(0, base, 0deg);                  // 1 layer: 30deg ang2 unused
    sh_speed(0, 0fx, 0fx);                    // :996 etSpeed(0,0) overrides :958
    sh_dist(0, 32fx);                         // :995 etDist(32)
    sh_xform(0, AT_PARENT(accel, spin));
    sh_task(0, at_parent);
    sh_fire(0);
}

// st03bs.ecl.txt:990-991 SHOOT: aim mode 8 (random angle + random speed),
// angle base = parent angle, spread pi, child speed = parent speed + U*1.5.
async sub at_parent() {
    wait(59);                                  // task starts at birth+1; xform at birth
    var rank: int = global(GVAR_RANK);
    var n: int = 8;                            // :981-988 E8 / N13 / H22 / L22
    if rank == 1 { n = 13; }
    if rank >= 2 { n = 22; }
    var px: fx = $self_x;
    var py: fx = $self_y;
    var pa: angle = $self_angle;
    var ps: fx = $self_speed;
    for i in 0..n {
        var ra: int = rand(65536);
        var off: int = ra - 32768;             // U_signed * pi in BAM
        var rv: int = rand(65536);
        var u: fx = (((rv - 32768) as fx) / 65536) + 0.5fx;
        _ = fire(CHILD_SHAPE, CHILD_COLOR, px, py, ps + u * 1.5fx,
                 pa + (off as angle), none, none);
    }
}

// st03bs.ecl.txt:1001-1032 BossCard3_at2: 10 bursts of `count` fireballs,
// ring at 32px, speed 0 -> random target speed over 60 frames.
async sub at2_burst(count: int) {
    var i: int = 10;                           // :1004 $A=10
    while i > 0 {
        var base: angle = rand(65536) as angle;             // :1020 %RANDRAD
        var rv: int = rand(65536);                          // :1024 %RANDF
        var u: fx = (((rv - 32768) as fx) / 65536) + 0.5fx;
        var target: fx = 0.5fx + u * 1.0fx;
        ring_burst(count, base, target / 60fx);
        i = i - 1;
        wait(10);
    }
}

// st03bs.ecl.txt:1034-1082 BossCard3_at3: one burst, fixed target speed per rank.
async sub at3_burst(count: int, target: fx) {
    var base: angle = rand(65536) as angle;    // :1061 %RANDRAD
    ring_burst(count, base, target / 60fx);
    wait(10);
}

sub ring_burst(count: int, base: angle, delta: fx) {
    sh_reset(0);
    sh_sprite(0, RING_SHAPE, RING_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, count, 1);
    sh_angle(0, base, 0deg);
    sh_speed(0, 0fx, 0fx);                     // :1026/:1076 etSpeed(0,0)
    sh_dist(0, 32fx);                          // :1025/:1075 etDist(32)
    sh_xform(0, RAMP(delta));
    sh_fire(0);
}

// st03bs.ecl.txt:744-949. $GI0 kept in enemy int slot 0 (shared with boss_et_break).
async sub boss_attack() {
    var rank: int = global(GVAR_RANK);
    var accel: fx = 0.02fx;
    if rank >= 2 { accel = 0.03fx; }
    var at2_count: int = 8;                    // :1011-1017 E8 N8 H12 L16
    if rank == 2 { at2_count = 12; }
    if rank >= 3 { at2_count = 16; }
    var at3_count: int = 10;                   // :1052-1058 E10 N20 H40 L55
    if rank == 1 { at3_count = 20; }
    if rank == 2 { at3_count = 40; }
    if rank >= 3 { at3_count = 55; }
    var at3_speed: fx = 0.5fx;                 // :1065-1072 E0.5 N0.5 H0.8 L1.5
    if rank == 2 { at3_speed = 0.8fx; }
    if rank >= 3 { at3_speed = 1.5fx; }
    var small: int = 30;                       // !ENH waits 30; Lunatic skips
