    spawn boss_et_break();                     // :781 at t=150

    loop {
        set_self_int(0, 10);                   // :785 $GI0=10, :784 %F0=-2deg
        spawn at_ring(-2deg, accel);
        move_to(60, -110fx, 256fx, EASE_QUAD_OUT);
        wait(60);
        set_self_int(0, -1);
        wait(small);
        wait(30);
        set_self_int(0, 9);
        spawn at_ring(-2deg, accel);
        move_to(60, 110fx, 192fx, EASE_QUAD_OUT);
        wait(60);
        set_self_int(0, -1);
        wait(small);
        wait(60);                              // :809 EffChargePoint3 + :810 wait
        wait(small);
        set_self_int(0, 10);
        move_to(far, -180fx, 430fx, EASE_QUAD_OUT);
        wait(far);
        set_self_int(0, -1);
        wait(tail);
        spawn at3_burst(at3_count, at3_speed);
        set_self_int(0, 9);
        move_to(far, 180fx, 430fx, EASE_QUAD_OUT);
        wait(far);
        set_self_int(0, -1);
        wait(tail);
        spawn at3_burst(at3_count, at3_speed);
        set_self_int(0, 10);
        move_to(60, 0fx, 224fx, EASE_QUAD_OUT);
        wait(60);
        spawn at2_burst(at2_count);
        set_self_int(0, -1);
        wait(small);
        wait(120);
        wait(small);
        set_self_int(0, 9);                    // :868 %F0=+2deg
        spawn at_ring(2deg, accel);
        move_to(60, 160fx, 64fx, EASE_QUAD_OUT);
        wait(60);
        set_self_int(0, -1);
        wait(small);
        wait(30);
        set_self_int(0, 10);
        spawn at_ring(2deg, accel);
        move_to(60, -160fx, 128fx, EASE_QUAD_OUT);
        wait(60);
        set_self_int(0, -1);
        wait(small);
        wait(60);
        wait(30);
        set_self_int(0, 9);
        move_to(far, 180fx, 430fx, EASE_QUAD_OUT);
        wait(far);
        set_self_int(0, -1);
        wait(tail);
        spawn at3_burst(at3_count, at3_speed);
        set_self_int(0, 10);
        move_to(far, -180fx, 430fx, EASE_QUAD_OUT);
        wait(far);
        set_self_int(0, -1);
        wait(tail);
        spawn at3_burst(at3_count, at3_speed);
        set_self_int(0, 9);
        move_to(60, 0fx, 224fx, EASE_QUAD_OUT);
        wait(60);
        spawn at2_burst(at2_count);
        set_self_int(0, -1);
        wait(30);
        wait(120);
        wait(30);
