}

// Real boss carries the phase. HP 1800 is the source entry lifeSet; no DPS in the shell.
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);                          // :23-24 setHurtbox/ setHitbox(48,48) -> r24
    set_hurtbox(24fx);
    spell_begin(0, SPELL_ID, boss_attack, SPELL_TIME, SPELL_BONUS, SPELL_NO_CLEAR, 0);
    wait_spell();
    // BossDead timeout exit (:1118-1141): kill helpers, +60 frames, clear bullets.
    wait(60);
    clear_bullets_at(0fx, 224fx, 1024fx, 0);
    loop { wait(60); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, boss_main);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
